   675		dirty := worktreeDirty(ctx, opts.Runner, repoDir)
   676		if source.Commit == head {
   677			axes["head"] = staleAxis{State: "ok", Current: head, Indexed: source.Commit}
   678		} else {
   679			axes["head"] = staleAxis{State: "stale", Current: head, Indexed: source.Commit}
   680		}
   681		if source.Branch == "" || source.Branch == branch {
   682			axes["branch_tip"] = staleAxis{State: "ok", Current: branch, Indexed: source.Branch}
   683		} else {
   684			axes["branch_tip"] = staleAxis{State: "stale", Current: branch, Indexed: source.Branch}
   685		}
   686		switch {
   687		case dirty && source.WorktreeMode != "worktree":
   688			axes["worktree"] = staleAxis{State: "dirty-unindexed", Detail: "semantic index is based on committed HEAD"}
   689		case dirty && source.WorktreeHash != "" && source.WorktreeHash != worktreeFingerprint(ctx, opts.Runner, repoDir):
   690			axes["worktree"] = staleAxis{State: "dirty-stale", Detail: "dirty worktree changed since semantic indexing"}
   691		case dirty:
   692			axes["worktree"] = staleAxis{State: "dirty-indexed"}
   693		case source.WorktreeMode == "worktree":
   694			axes["worktree"] = staleAxis{State: "worktree-overlay-stale", Detail: "active semantic index was built from dirty content but worktree is now clean"}
   695		default:
   696			axes["worktree"] = staleAxis{State: "clean"}
   697		}
   698		if err := validateSemanticSchema(source.SchemaVersion); err != nil {
   699			axes["provider"] = staleAxis{State: "unsafe", Detail: err.Error()}
   700		} else if !source.NoEgressVerified {
   701			axes["provider"] = staleAxis{State: "degraded", Detail: "provider no-egress status was not verified"}
   702		} else {
   703			axes["provider"] = staleAxis{State: "ok", Detail: source.Provider + " " + source.ProviderVersion}
   704		}
   705		if len(source.PartialFailures) > 0 {
   706			axes["semantic_completeness"] = staleAxis{State: "degraded", Detail: strconv.Itoa(len(source.PartialFailures)) + " partial failures"}
   707		} else {
   708			axes["semantic_completeness"] = staleAxis{State: "ok"}
   709		}
   710		severity := aggregateStaleSeverity(axes)
   711		return staleReport{Severity: severity, Axes: axes, Warnings: source.Warnings}, nil
