   794	func findSemanticSymbols(snapshotPath, query string, limit int) ([]semanticRecord, error) {
   795		f, err := os.Open(snapshotPath)
   796		if err != nil {
   797			return nil, fmt.Errorf("open semantic snapshot: %w", err)
   798		}
   799		defer f.Close()
   800		query = strings.ToLower(strings.TrimSpace(query))
   801		scanner := bufio.NewScanner(f)
   802		scanner.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
   803		first := true
   804		var results []semanticRecord
   805		for scanner.Scan() {
   806			if first {
   807				first = false
   808				continue
   809			}
   810			var record semanticRecord
   811			if err := json.Unmarshal(scanner.Bytes(), &record); err != nil {
   812				return nil, err
   813			}
   814			if record.RecordType != "symbol" {
   815				continue
   816			}
   817			fields := []string{record.Name, record.QualifiedName, record.Signature, record.FilePath}
   818			for _, field := range fields {
   819				if strings.Contains(strings.ToLower(field), query) {
   820					results = append(results, record)
   821					break
   822				}
   823			}
   824			if len(results) >= limit {
   825				break
   826			}
   827		}
   828		return results, scanner.Err()
   829	}
